def load() -> pd.DataFrame:
    import glob
    import os
    import pandas as pd

    pattern = 'data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Identity Theft data/*'
    paths = sorted(glob.glob(pattern))
    if len(paths) == 0:
        raise FileNotFoundError(f'No files matched pattern: {pattern}')

    dfs = []
    for p in paths:
        try:
            df = pd.read_csv(p)
        except Exception:
            # fallback for odd encodings/delimiters
            df = pd.read_csv(p, encoding='latin-1')
        df['__source_file'] = os.path.basename(p)
        dfs.append(df)
    return pd.concat(dfs, ignore_index=True, sort=False)

def process(loadIdTheftCsvs) -> pd.DataFrame:
    import pandas as pd

    df = loadIdTheftCsvs
    meta = []
    for c in df.columns:
        meta.append({
            'column': c,
            'non_null': int(df[c].notna().sum()),
            'dtype': str(df[c].dtype),
            'sample_values': ', '.join([str(x) for x in df[c].dropna().astype(str).head(5).tolist()])
        })
    return pd.DataFrame(meta).sort_values(['non_null','column'], ascending=[False, True]).reset_index(drop=True)
